-- Design §6.2 in the database. The function below is generated by transitionFunctionSql() in
-- src/modules/trades/domain/stateMachineSql.ts: the TypeScript map is the source of truth and this
-- is its copy, so a service that forgets canTransition, a job that updates status directly and a
-- psql session are refused the same jumps. A unit test fails if the two ever diverge.
--
-- Two triggers hang off it. The guard refuses an invalid jump with SQLSTATE KT010 and stamps the
-- clock itself, so a caller cannot backdate a transition. The recorder writes trade_state_changes,
-- because an audit trail that depends on every caller remembering to write it is decorative; the
-- log is append-only (migration 0017), so the row it writes can never be edited afterwards.
-- A counter-proposal leaves the status where it is and so writes no state change: it is recorded in
-- trade_activity as COUNTER_PROPOSED (conflict C6).
CREATE OR REPLACE FUNCTION trade.is_valid_transition(
  action trade.trade_action, from_status trade.trade_status, to_status trade.trade_status
) RETURNS boolean LANGUAGE sql IMMUTABLE PARALLEL SAFE AS $$
  SELECT (action::text, from_status::text, to_status::text) IN (
    ('SEND', 'DRAFT', 'PENDING_COUNTERPARTY'),
    ('SEND', 'DRAFT', 'UNDER_PROPOSAL_REVIEW'),
    ('SEND', 'DRAFT', 'AWAITING_ACCEPTANCE'),
    ('CLAIM_INVITATION', 'PENDING_COUNTERPARTY', 'UNDER_PROPOSAL_REVIEW'),
    ('CLAIM_INVITATION', 'PENDING_COUNTERPARTY', 'AWAITING_ACCEPTANCE'),
    ('EXPIRE', 'PENDING_COUNTERPARTY', 'EXPIRED'),
    ('EXPIRE', 'PENDING_PAYMENT', 'EXPIRED'),
    ('CLEAR_REVIEW', 'UNDER_PROPOSAL_REVIEW', 'AWAITING_ACCEPTANCE'),
    ('REJECT_REVIEW', 'UNDER_PROPOSAL_REVIEW', 'REJECTED'),
    ('COUNTER_PROPOSE', 'AWAITING_ACCEPTANCE', 'AWAITING_ACCEPTANCE'),
    ('ACCEPT', 'AWAITING_ACCEPTANCE', 'PENDING_PAYMENT'),
    ('DECLINE', 'AWAITING_ACCEPTANCE', 'DECLINED'),
    ('CANCEL', 'DRAFT', 'CANCELLED'),
    ('CANCEL', 'PENDING_COUNTERPARTY', 'CANCELLED'),
    ('CANCEL', 'UNDER_PROPOSAL_REVIEW', 'CANCELLED'),
    ('CANCEL', 'AWAITING_ACCEPTANCE', 'CANCELLED'),
    ('CANCEL', 'PENDING_PAYMENT', 'CANCELLED'),
    ('FUND', 'PENDING_PAYMENT', 'FUNDED'),
    ('BEGIN_CUSTODY', 'FUNDED', 'SHIPPED'),
    ('REFUND_CANCELLATION', 'FUNDED', 'CANCELLED_REFUNDED'),
    ('DELIVERY_SIGNAL', 'SHIPPED', 'INSPECTION'),
    ('DELIVERY_SIGNAL', 'SHIPPED', 'UNCONFIRMED_DELIVERY'),
    ('CONFIRM_RECEIPT', 'UNCONFIRMED_DELIVERY', 'INSPECTION'),
    ('GRACE_ELAPSED', 'UNCONFIRMED_DELIVERY', 'INSPECTION'),
    ('COMPLETE', 'INSPECTION', 'COMPLETED'),
    ('INSPECTION_ELAPSED', 'INSPECTION', 'COMPLETED'),
    ('SETTLE', 'COMPLETED', 'SETTLED'),
    ('DISPUTE', 'SHIPPED', 'DISPUTED'),
    ('DISPUTE', 'UNCONFIRMED_DELIVERY', 'DISPUTED'),
    ('DISPUTE', 'INSPECTION', 'DISPUTED'),
    ('RESOLVE_DISPUTE', 'DISPUTED', 'RESOLVED_REFUNDED'),
    ('RESOLVE_DISPUTE', 'DISPUTED', 'RESOLVED_RELEASED')
  );
$$;
--> statement-breakpoint
CREATE FUNCTION trade.guard_status_transition() RETURNS trigger
  LANGUAGE plpgsql AS $$
BEGIN
  IF NEW.status_action IS NULL OR NEW.status_actor_type IS NULL THEN
    RAISE EXCEPTION 'komtru: a trade status change must name its action and its actor'
      USING ERRCODE = 'KT010';
  END IF;
  IF NOT trade.is_valid_transition(NEW.status_action, OLD.status, NEW.status) THEN
    RAISE EXCEPTION 'komtru: % cannot move trade % from % to %',
      NEW.status_action, OLD.trade_code, OLD.status, NEW.status
      USING ERRCODE = 'KT010';
  END IF;
  NEW.status_changed_at := now();
  NEW.updated_at := now();
  RETURN NEW;
END
$$;
--> statement-breakpoint
CREATE FUNCTION trade.record_state_change() RETURNS trigger
  LANGUAGE plpgsql AS $$
BEGIN
  INSERT INTO trade.trade_state_changes
    (occurred_at, trade_id, from_status, to_status, action, actor_type, actor_id, reason, metadata)
  VALUES
    (NEW.status_changed_at, NEW.id, OLD.status, NEW.status, NEW.status_action,
     NEW.status_actor_type, NEW.status_actor_id, NEW.status_reason, NEW.status_context);
  RETURN NULL;
END
$$;
--> statement-breakpoint
CREATE TRIGGER trade_guard_status_transition BEFORE UPDATE ON trade.trades
  FOR EACH ROW WHEN (OLD.status IS DISTINCT FROM NEW.status)
  EXECUTE FUNCTION trade.guard_status_transition();
--> statement-breakpoint
CREATE TRIGGER trade_record_state_change AFTER UPDATE ON trade.trades
  FOR EACH ROW WHEN (OLD.status IS DISTINCT FROM NEW.status)
  EXECUTE FUNCTION trade.record_state_change();
